// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IRICEManager {
    function spendRICEEmergencyForPowerUp(
        address player,
        uint256 amount,
        bytes32 operationHash
    ) external;
}

contract PowerUpManager {
    // ================================
    // STORAGE
    // ================================
    mapping(address => mapping(uint256 => uint256)) public levels; // player => powerUpId => level
    mapping(uint256 => uint256) public powerUpBaseCosts; // powerUpId => base cost
    mapping(uint256 => uint256) public powerUpMaxLevels; // powerUpId => max level
    mapping(uint256 => mapping(uint256 => uint256)) public powerUpLevelCosts; // powerUpId => level => cost

    // Security and ownership
    address public gameOwner; // Address autorisée à gérer le contrat
    bool public paused = false;

    // Security key for signing operations (set by game owner)
    bytes32 public securityKey;
    bool public securityKeySet = false;

    // Contract addresses
    address public riceManager;
    address public gameServer;

    // Anti-spam protection
    mapping(address => uint256) public lastUpgradeTimestamp;
    uint256 public constant MIN_TIME_BETWEEN_UPGRADES = 30 seconds;

    // Prevent upgrade reuse
    mapping(bytes32 => bool) public usedUpgradeHashes;

    // Events
    event PowerUpUpgraded(
        address indexed player,
        uint256 indexed powerUpId,
        uint256 oldLevel,
        uint256 newLevel,
        uint256 cost,
        bytes32 upgradeHash
    );
    event PowerUpConfigured(
        uint256 indexed powerUpId,
        uint256 baseCost,
        uint256 maxLevel
    );
    event GameOwnerUpdated(address indexed oldOwner, address indexed newOwner);
    event ContractPaused(bool paused);
    event GameServerUpdated(
        address indexed oldServer,
        address indexed newServer
    );

    modifier onlyGameOwner() {
        require(
            msg.sender == gameOwner,
            "Only game owner can call this function"
        );
        _;
    }

    modifier onlyGameServer() {
        require(msg.sender == gameServer, "Not authorized");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Contract is paused");
        _;
    }

    constructor(address _riceManager, address _gameServer) {
        gameOwner = msg.sender;
        riceManager = _riceManager;
        gameServer = _gameServer;
    }

    /**
     * @dev Sets the security key for signing operations
     * @param _securityKey The security key to set
     */
    function setSecurityKey(bytes32 _securityKey) external onlyGameOwner {
        securityKey = _securityKey;
        securityKeySet = true;
    }

    /**
     * @dev Updates the game owner
     * @param _newOwner The new game owner address
     */
    function setGameOwner(address _newOwner) external onlyGameOwner {
        require(_newOwner != address(0), "Invalid address");
        address oldOwner = gameOwner;
        gameOwner = _newOwner;
        emit GameOwnerUpdated(oldOwner, _newOwner);
    }

    /**
     * @dev Pauses or unpauses the contract
     * @param _paused True to pause, false to unpause
     */
    function setPaused(bool _paused) external onlyGameOwner {
        paused = _paused;
        emit ContractPaused(_paused);
    }

    /**
     * @dev Updates the game server address
     * @param _gameServer The new game server address
     */
    function setGameServer(address _gameServer) external onlyGameOwner {
        require(_gameServer != address(0), "Invalid address");
        address oldServer = gameServer;
        gameServer = _gameServer;
        emit GameServerUpdated(oldServer, _gameServer);
    }

    /**
     * @dev Updates the RICEManager address
     * @param _riceManager The new RICEManager address
     */
    function setRiceManager(address _riceManager) external onlyGameOwner {
        require(_riceManager != address(0), "Invalid address");
        riceManager = _riceManager;
    }

    /// @notice Set base cost and max level of a power-up (on-chain)
    function setPowerUp(
        uint256 powerUpId,
        uint256 baseCost,
        uint256 maxLevel
    ) external onlyGameServer whenNotPaused {
        require(baseCost > 0, "Base cost must be greater than 0");
        require(maxLevel > 0, "Max level must be greater than 0");

        powerUpBaseCosts[powerUpId] = baseCost;
        powerUpMaxLevels[powerUpId] = maxLevel;

        // Initialize level costs with a progression
        for (uint256 level = 1; level <= maxLevel; level++) {
            powerUpLevelCosts[powerUpId][level] = baseCost * level * level; // Quadratic progression
        }

        emit PowerUpConfigured(powerUpId, baseCost, maxLevel);
    }

    /// @notice Upgrade power-up with signature verification
    function upgradePowerUp(
        address player,
        uint256 powerUpId,
        bytes32 upgradeHash,
        bytes memory signature
    ) external whenNotPaused {
        require(!usedUpgradeHashes[upgradeHash], "Upgrade hash already used");
        require(
            block.timestamp >=
                lastUpgradeTimestamp[player] + MIN_TIME_BETWEEN_UPGRADES,
            "Too soon since last upgrade"
        );
        require(securityKeySet, "Security key not set");

        uint256 currentLevel = levels[player][powerUpId];
        uint256 maxLevel = powerUpMaxLevels[powerUpId];
        require(maxLevel > 0, "Power-up not initialized");
        require(currentLevel < maxLevel, "Already max level");

        uint256 cost = powerUpLevelCosts[powerUpId][currentLevel + 1];

        // Verify the signature
        bytes32 messageHash = keccak256(
            abi.encodePacked(
                "UPGRADE_POWERUP",
                player,
                powerUpId,
                cost,
                upgradeHash
            )
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        // Recover the signer from the signature
        address signer = recoverSigner(ethSignedMessageHash, signature);

        // The signer should be the game owner (who has the security key)
        require(signer == gameOwner, "Invalid signature");

        // Mark hash as used
        usedUpgradeHashes[upgradeHash] = true;
        lastUpgradeTimestamp[player] = block.timestamp;

        // Spend RICE and upgrade (now using RICE units, not wei)
        IRICEManager(riceManager).spendRICEEmergencyForPowerUp(
            player,
            cost, // Cost in RICE units, not wei
            bytes32(0)
        );
        levels[player][powerUpId]++;

        emit PowerUpUpgraded(
            player,
            powerUpId,
            currentLevel,
            levels[player][powerUpId],
            cost,
            upgradeHash
        );
    }

    /// @notice Emergency function to set power-up without signature (for testing)
    function setPowerUpEmergency(
        uint256 powerUpId,
        uint256 baseCost,
        uint256 maxLevel
    ) external onlyGameOwner whenNotPaused {
        require(baseCost > 0, "Base cost must be greater than 0");
        require(maxLevel > 0, "Max level must be greater than 0");

        powerUpBaseCosts[powerUpId] = baseCost;
        powerUpMaxLevels[powerUpId] = maxLevel;

        // Initialize level costs with a progression
        for (uint256 level = 1; level <= maxLevel; level++) {
            powerUpLevelCosts[powerUpId][level] = baseCost * level * level; // Quadratic progression
        }

        emit PowerUpConfigured(powerUpId, baseCost, maxLevel);
    }

    /// @notice Emergency function to upgrade power-up without signature (for testing)
    function upgradePowerUpEmergency(
        address player,
        uint256 powerUpId
    ) external whenNotPaused {
        uint256 currentLevel = levels[player][powerUpId];
        uint256 maxLevel = powerUpMaxLevels[powerUpId];
        require(maxLevel > 0, "Power-up not initialized");
        require(currentLevel < maxLevel, "Already max level");

        uint256 cost = powerUpLevelCosts[powerUpId][currentLevel + 1];

        IRICEManager(riceManager).spendRICEEmergencyForPowerUp(
            player,
            cost, // Convert RICE to wei
            bytes32(0)
        );
        levels[player][powerUpId]++;

        emit PowerUpUpgraded(
            player,
            powerUpId,
            currentLevel,
            levels[player][powerUpId],
            cost,
            bytes32(0)
        );
    }

    /// @notice Return levels of the 10 first power-ups for a player
    function getPowerUpLevels(
        address player
    ) external view returns (uint256[] memory) {
        uint256 count = 10;
        uint256[] memory result = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            // Return level + 1 so players start at level 1 instead of 0
            result[i] = levels[player][i] + 1;
        }
        return result;
    }

    /// @notice Return base cost and maxLevel of a power-up
    function getPowerUpConfig(
        uint256 powerUpId
    ) external view returns (uint256 baseCost, uint256 maxLevel) {
        return (powerUpBaseCosts[powerUpId], powerUpMaxLevels[powerUpId]);
    }

    /// @notice Get the cost to upgrade to a specific level
    function getPowerUpLevelCost(
        uint256 powerUpId,
        uint256 level
    ) external view returns (uint256 cost) {
        return powerUpLevelCosts[powerUpId][level];
    }

    /// @notice Get the cost to upgrade the next level for a player
    function getPowerUpUpgradeCost(
        address player,
        uint256 powerUpId
    ) external view returns (uint256 cost) {
        uint256 currentLevel = levels[player][powerUpId];
        // Calculate cost for the next level (currentLevel + 1)
        return powerUpLevelCosts[powerUpId][currentLevel + 1];
    }

    /**
     * @dev Recovers the signer from a signature
     */
    function recoverSigner(
        bytes32 _ethSignedMessageHash,
        bytes memory _signature
    ) internal pure returns (address) {
        require(_signature.length == 65, "Invalid signature length");

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            r := mload(add(_signature, 32))
            s := mload(add(_signature, 64))
            v := byte(0, mload(add(_signature, 96)))
        }

        if (v < 27) {
            v += 27;
        }

        require(v == 27 || v == 28, "Invalid signature 'v' value");

        return ecrecover(_ethSignedMessageHash, v, r, s);
    }

    /// @notice Get contract information
    function getContractInfo()
        external
        view
        returns (
            address _gameOwner,
            bool _paused,
            uint256 _minTimeBetweenUpgrades,
            bool _securityKeySet
        )
    {
        return (gameOwner, paused, MIN_TIME_BETWEEN_UPGRADES, securityKeySet);
    }
}

contracts/RICEManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract RICEManager {
    mapping(address => uint256) public balances;

    // Security and ownership
    address public gameOwner; // Address autorisée à gérer le contrat
    bool public paused = false;

    // Security key for signing operations (set by game owner)
    bytes32 public securityKey;
    bool public securityKeySet = false;

    // ScoreBoard contract address (set by game owner)
    address public scoreBoardAddress;

    // Anti-spam protection
    mapping(address => uint256) public lastOperationTimestamp;
    uint256 public constant MIN_TIME_BETWEEN_OPERATIONS = 30 seconds;

    // Prevent operation reuse
    mapping(bytes32 => bool) public usedOperationHashes;

    // Contract addresses
    address public powerUpManagerAddress;

    // Daily reveal tracking
    mapping(address => uint256) public lastDailyRevealTimestamp;
    uint256 public constant DAILY_REVEAL_COOLDOWN = 24 hours;

    event RICEAdded(
        address indexed player,
        uint256 amount,
        bytes32 operationHash
    );
    event RICESpent(
        address indexed player,
        uint256 amount,
        bytes32 operationHash
    );
    event DailyRevealRICEAdded(
        address indexed player,
        uint256 amount,
        bytes32 operationHash
    );
    event GameOwnerUpdated(address indexed oldOwner, address indexed newOwner);
    event ContractPaused(bool paused);
    event SecurityKeyUpdated(bytes32 newKey);
    event ScoreBoardAddressUpdated(address indexed newAddress);

    modifier onlyGameOwner() {
        require(
            msg.sender == gameOwner,
            "Only game owner can call this function"
        );
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Contract is paused");
        _;
    }

    modifier onlyScoreBoard() {
        require(
            msg.sender == scoreBoardAddress,
            "Only ScoreBoard can call this function"
        );
        _;
    }

    modifier onlyPowerUpManager() {
        require(
            msg.sender == powerUpManagerAddress,
            "Only PowerUpManager can call this function"
        );
        _;
    }

    constructor() {
        gameOwner = msg.sender;
    }

    /**
     * @dev Adds RICE to a player's balance with signature verification
     * @param player The player's address
     * @param amount The amount of RICE to add (in RICE units, not wei)
     * @param operationHash Unique operation hash to verify authenticity
     * @param signature Signature created with the security key
     */
    function addRICE(
        address player,
        uint256 amount,
        bytes32 operationHash,
        bytes memory signature
    ) external whenNotPaused {
        require(amount > 0, "Amount must be greater than 0");
        require(
            !usedOperationHashes[operationHash],
            "Operation hash already used"
        );
        require(
            block.timestamp >=
                lastOperationTimestamp[player] + MIN_TIME_BETWEEN_OPERATIONS,
            "Too soon since last operation"
        );
        require(securityKeySet, "Security key not set");

        // Verify the signature
        bytes32 messageHash = keccak256(
            abi.encodePacked("ADD_RICE", player, amount, operationHash)
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        // Recover the signer from the signature
        address signer = recoverSigner(ethSignedMessageHash, signature);

        // The signer should be the game owner (who has the security key)
        require(signer == gameOwner, "Invalid signature");

        // Mark hash as used
        usedOperationHashes[operationHash] = true;
        lastOperationTimestamp[player] = block.timestamp;

        balances[player] += amount;
        emit RICEAdded(player, amount, operationHash);
    }

    /**
     * @dev Adds RICE from daily reveal with signature verification
     * @param player The player's address
     * @param amount The amount of RICE to add (in RICE units, not wei)
     * @param operationHash Unique operation hash to verify authenticity
     * @param signature Signature created with the security key
     */
    function addDailyRevealRICE(
        address player,
        uint256 amount,
        bytes32 operationHash,
        bytes memory signature
    ) external whenNotPaused {
        require(amount > 0, "Amount must be greater than 0");
        require(
            !usedOperationHashes[operationHash],
            "Operation hash already used"
        );
        require(
            block.timestamp >=
                lastDailyRevealTimestamp[player] + DAILY_REVEAL_COOLDOWN,
            "Daily reveal already claimed today"
        );
        require(securityKeySet, "Security key not set");

        // Verify the signature
        bytes32 messageHash = keccak256(
            abi.encodePacked("DAILY_REVEAL_RICE", player, amount, operationHash)
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        // Recover the signer from the signature
        address signer = recoverSigner(ethSignedMessageHash, signature);

        // The signer should be the game owner (who has the security key)
        require(signer == gameOwner, "Invalid signature");

        // Mark hash as used
        usedOperationHashes[operationHash] = true;
        lastDailyRevealTimestamp[player] = block.timestamp;

        balances[player] += amount;
        emit DailyRevealRICEAdded(player, amount, operationHash);
    }

    /**
     * @dev Spends RICE from a player's balance with signature verification
     * @param player The player's address
     * @param amount The amount of RICE to spend (in RICE units, not wei)
     * @param operationHash Unique operation hash to verify authenticity
     * @param signature Signature created with the security key
     */
    function spendRICE(
        address player,
        uint256 amount,
        bytes32 operationHash,
        bytes memory signature
    ) external whenNotPaused {
        require(amount > 0, "Amount must be greater than 0");
        require(balances[player] >= amount, "Not enough RICE");
        require(
            !usedOperationHashes[operationHash],
            "Operation hash already used"
        );
        require(
            block.timestamp >=
                lastOperationTimestamp[player] + MIN_TIME_BETWEEN_OPERATIONS,
            "Too soon since last operation"
        );
        require(securityKeySet, "Security key not set");

        // Verify the signature
        bytes32 messageHash = keccak256(
            abi.encodePacked("SPEND_RICE", player, amount, operationHash)
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        // Recover the signer from the signature
        address signer = recoverSigner(ethSignedMessageHash, signature);

        // The signer should be the game owner (who has the security key)
        require(signer == gameOwner, "Invalid signature");

        // Mark hash as used
        usedOperationHashes[operationHash] = true;
        lastOperationTimestamp[player] = block.timestamp;

        balances[player] -= amount;
        emit RICESpent(player, amount, operationHash);
    }

    /**
     * @dev Emergency function to add RICE without signature (for testing)
     * Only accessible by the ScoreBoard contract
     * @param player The player's address
     * @param amount The amount of RICE to add (in RICE units, not wei)
     * @param operationHash Unique operation hash
     */
    function addRICEEmergency(
        address player,
        uint256 amount,
        bytes32 operationHash
    ) external onlyScoreBoard whenNotPaused {
        require(amount > 0, "Amount must be greater than 0");
        require(
            !usedOperationHashes[operationHash],
            "Operation hash already used"
        );

        usedOperationHashes[operationHash] = true;
        balances[player] += amount;
        emit RICEAdded(player, amount, operationHash);
    }

    /**
     * @dev Emergency function to spend RICE without signature (for testing)
     * Only accessible by the game owner
     * @param player The player's address
     * @param amount The amount of RICE to spend (in RICE units, not wei)
     * @param operationHash Unique operation hash
     */
    function spendRICEEmergency(
        address player,
        uint256 amount,
        bytes32 operationHash
    ) external onlyGameOwner whenNotPaused {
        require(amount > 0, "Amount must be greater than 0");
        require(balances[player] >= amount, "Not enough RICE");
        require(
            !usedOperationHashes[operationHash],
            "Operation hash already used"
        );

        usedOperationHashes[operationHash] = true;
        balances[player] -= amount;
        emit RICESpent(player, amount, operationHash);
    }

    /**
     * @dev Emergency function to spend RICE for PowerUpManager without signature
     * Only accessible by the PowerUpManager contract
     * @param player The player's address
     * @param amount The amount of RICE to spend (in RICE units, not wei)
     * @param operationHash Unique operation hash
     */
    function spendRICEEmergencyForPowerUp(
        address player,
        uint256 amount,
        bytes32 operationHash
    ) external onlyPowerUpManager whenNotPaused {
        require(amount > 0, "Amount must be greater than 0");
        require(balances[player] >= amount, "Not enough RICE");
        require(
            !usedOperationHashes[operationHash],
            "Operation hash already used"
        );

        usedOperationHashes[operationHash] = true;
        balances[player] -= amount;
        emit RICESpent(player, amount, operationHash);
    }

    /**
     * @dev Recovers the signer from a signature
     */
    function recoverSigner(
        bytes32 _ethSignedMessageHash,
        bytes memory _signature
    ) internal pure returns (address) {
        require(_signature.length == 65, "Invalid signature length");

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            r := mload(add(_signature, 32))
            s := mload(add(_signature, 64))
            v := byte(0, mload(add(_signature, 96)))
        }

        if (v < 27) {
            v += 27;
        }

        require(v == 27 || v == 28, "Invalid signature 'v' value");

        return ecrecover(_ethSignedMessageHash, v, r, s);
    }

    /**
     * @dev Gets the RICE balance for a player (in RICE units, not wei)
     * @param player The player's address
     * @return The player's RICE balance
     */
    function getBalance(address player) external view returns (uint256) {
        return balances[player];
    }

    /**
     * @dev Checks if player can claim daily reveal
     * @param player The player's address
     * @return True if player can claim daily reveal
     */
    function canClaimDailyReveal(address player) external view returns (bool) {
        return
            block.timestamp >=
            lastDailyRevealTimestamp[player] + DAILY_REVEAL_COOLDOWN;
    }

    /**
     * @dev Gets the time until next daily reveal can be claimed
     * @param player The player's address
     * @return Time in seconds until next claim
     */
    function getTimeUntilNextDailyReveal(
        address player
    ) external view returns (uint256) {
        uint256 nextClaimTime = lastDailyRevealTimestamp[player] +
            DAILY_REVEAL_COOLDOWN;
        if (block.timestamp >= nextClaimTime) {
            return 0;
        }
        return nextClaimTime - block.timestamp;
    }

    /**
     * @dev Administrative functions
     */
    function setGameOwner(address _newOwner) public onlyGameOwner {
        require(_newOwner != address(0), "Invalid address");
        address oldOwner = gameOwner;
        gameOwner = _newOwner;
        emit GameOwnerUpdated(oldOwner, _newOwner);
    }

    function setPaused(bool _paused) public onlyGameOwner {
        paused = _paused;
        emit ContractPaused(_paused);
    }

    /**
     * @dev Sets the security key for signing operations
     * @param _securityKey The new security key
     */
    function setSecurityKey(bytes32 _securityKey) public onlyGameOwner {
        securityKey = _securityKey;
        securityKeySet = true;
        emit SecurityKeyUpdated(_securityKey);
    }

    /**
     * @dev Sets the ScoreBoard contract address
     * @param _scoreBoardAddress The ScoreBoard contract address
     */
    function setScoreBoardAddress(
        address _scoreBoardAddress
    ) public onlyGameOwner {
        require(_scoreBoardAddress != address(0), "Invalid address");
        scoreBoardAddress = _scoreBoardAddress;
        emit ScoreBoardAddressUpdated(_scoreBoardAddress);
    }

    /**
     * @dev Sets the PowerUpManager contract address
     * @param _powerUpManagerAddress The PowerUpManager contract address
     */
    function setPowerUpManagerAddress(
        address _powerUpManagerAddress
    ) public onlyGameOwner {
        require(_powerUpManagerAddress != address(0), "Invalid address");
        powerUpManagerAddress = _powerUpManagerAddress;
    }

    function getContractInfo()
        public
        view
        returns (
            address _gameOwner,
            bool _paused,
            uint256 _minTimeBetweenOperations,
            bool _securityKeySet,
            uint256 _dailyRevealCooldown
        )
    {
        return (
            gameOwner,
            paused,
            MIN_TIME_BETWEEN_OPERATIONS,
            securityKeySet,
            DAILY_REVEAL_COOLDOWN
        );
    }
}

contracts/ScoreBoard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

// Interface for RICEManager contract
interface IRICEManager {
    function addRICE(
        address player,
        uint256 amount,
        bytes32 operationHash,
        bytes memory signature
    ) external;

    function addRICEEmergency(
        address player,
        uint256 amount,
        bytes32 operationHash
    ) external;
}

contract ScoreBoard {
    struct Score {
        uint256 score;
        uint256 timestamp;
        string playerName;
        bytes32 gameHash; // Hash to verify score authenticity
    }

    struct LeaderboardEntry {
        uint256 score;
        string playerName;
        address playerAddress;
    }

    mapping(address => Score[]) public playerScores;
    mapping(address => uint256) public playerBestScore;
    mapping(address => uint256) public lastScoreTimestamp; // Anti-spam protection
    mapping(bytes32 => bool) public usedGameHashes; // Prevent score reuse

    // Global leaderboard tracking
    address[] public allPlayers;
    mapping(address => bool) public playerExists;
    mapping(address => string) public playerNames; // Store player names

    uint256 public constant MIN_TIME_BETWEEN_SCORES = 30 seconds; // Minimum time between scores

    address public gameOwner; // Address authorized to manage the contract
    bool public paused = false;

    // RICEManager contract address
    address public riceManagerAddress;

    // Security key for signing scores (set by game owner)
    bytes32 public securityKey;
    bool public securityKeySet = false;

    event ScoreRecorded(
        address indexed player,
        uint256 score,
        uint256 timestamp,
        bytes32 gameHash
    );
    event ScoreRecordedWithRICE(
        address indexed player,
        uint256 score,
        uint256 riceReward,
        uint256 timestamp,
        bytes32 gameHash
    );
    event BestScoreUpdated(address indexed player, uint256 newBestScore);
    event GameOwnerUpdated(address indexed oldOwner, address indexed newOwner);
    event ContractPaused(bool paused);
    event SecurityKeyUpdated(bytes32 newKey);

    modifier onlyGameOwner() {
        require(
            msg.sender == gameOwner,
            "Only game owner can call this function"
        );
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Contract is paused");
        _;
    }

    constructor() {
        gameOwner = msg.sender;
    }

    /**
     * @dev Sets the RICEManager contract address
     * @param _riceManagerAddress The address of the RICEManager contract
     */
    function setRICEManagerAddress(
        address _riceManagerAddress
    ) public onlyGameOwner {
        require(_riceManagerAddress != address(0), "Invalid address");
        riceManagerAddress = _riceManagerAddress;
    }

    /**
     * @dev Records a score - ANY PLAYER CAN CALL THIS FUNCTION WITH VALID SIGNATURE
     * @param _score The score to record
     * @param _playerName The player's name
     * @param _gameHash Unique game hash to verify authenticity
     * @param _signature Signature created with the security key
     */
    function recordScore(
        uint256 _score,
        string memory _playerName,
        bytes32 _gameHash,
        bytes memory _signature
    ) public whenNotPaused {
        require(_score > 0, "Score must be greater than 0");
        require(!usedGameHashes[_gameHash], "Game hash already used");
        require(
            block.timestamp >=
                lastScoreTimestamp[msg.sender] + MIN_TIME_BETWEEN_SCORES,
            "Too soon since last score"
        );
        require(securityKeySet, "Security key not set");

        // Verify the signature
        bytes32 messageHash = keccak256(
            abi.encodePacked(_score, _playerName, msg.sender, _gameHash)
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        // Recover the signer from the signature
        address signer = recoverSigner(ethSignedMessageHash, _signature);

        // The signer should be the game owner (who has the security key)
        require(signer == gameOwner, "Invalid signature");

        // Mark hash as used
        usedGameHashes[_gameHash] = true;

        Score memory newScore = Score({
            score: _score,
            timestamp: block.timestamp,
            playerName: _playerName,
            gameHash: _gameHash
        });

        playerScores[msg.sender].push(newScore);
        lastScoreTimestamp[msg.sender] = block.timestamp;

        // Add player to global tracking if not already present
        if (!playerExists[msg.sender]) {
            allPlayers.push(msg.sender);
            playerExists[msg.sender] = true;
            playerNames[msg.sender] = _playerName;
        }

        // Update best score if this is higher
        if (_score > playerBestScore[msg.sender]) {
            playerBestScore[msg.sender] = _score;
            emit BestScoreUpdated(msg.sender, _score);
        }

        emit ScoreRecorded(msg.sender, _score, block.timestamp, _gameHash);
    }

    /**
     * @dev Records a score and adds RICE rewards in a single transaction
     * @param _score The score to record
     * @param _playerName The player's name
     * @param _riceReward The amount of RICE to add as reward
     * @param _gameHash Unique game hash to verify authenticity
     * @param _signature Signature created with the security key
     */
    function recordScoreWithRICE(
        uint256 _score,
        string memory _playerName,
        uint256 _riceReward,
        bytes32 _gameHash,
        bytes memory _signature
    ) public whenNotPaused {
        require(_score > 0, "Score must be greater than 0");
        require(_riceReward > 0, "RICE reward must be greater than 0");
        require(!usedGameHashes[_gameHash], "Game hash already used");
        require(
            block.timestamp >=
                lastScoreTimestamp[msg.sender] + MIN_TIME_BETWEEN_SCORES,
            "Too soon since last score"
        );
        require(securityKeySet, "Security key not set");
        require(riceManagerAddress != address(0), "RICEManager not configured");

        // Verify the signature - using the same format as the API
        bytes32 messageHash = keccak256(
            abi.encodePacked(
                _score,
                _playerName,
                _riceReward,
                msg.sender,
                _gameHash
            )
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        // Recover the signer from the signature
        address signer = recoverSigner(ethSignedMessageHash, _signature);

        // The signer should be the game owner (who has the security key)
        require(signer == gameOwner, "Invalid signature");

        // Mark hash as used
        usedGameHashes[_gameHash] = true;

        Score memory newScore = Score({
            score: _score,
            timestamp: block.timestamp,
            playerName: _playerName,
            gameHash: _gameHash
        });

        playerScores[msg.sender].push(newScore);
        lastScoreTimestamp[msg.sender] = block.timestamp;

        // Add player to global tracking if not already present
        if (!playerExists[msg.sender]) {
            allPlayers.push(msg.sender);
            playerExists[msg.sender] = true;
            playerNames[msg.sender] = _playerName;
        }

        // Update best score if this is higher
        if (_score > playerBestScore[msg.sender]) {
            playerBestScore[msg.sender] = _score;
            emit BestScoreUpdated(msg.sender, _score);
        }

        // Add RICE rewards via RICEManager (using emergency function since we already verified the signature)
        IRICEManager(riceManagerAddress).addRICEEmergency(
            msg.sender,
            _riceReward, // RICE reward in RICE units, not wei
            _gameHash
        );

        emit ScoreRecordedWithRICE(
            msg.sender,
            _score,
            _riceReward,
            block.timestamp,
            _gameHash
        );
    }

    /**
     * @dev Emergency function to record a score without signature (for testing)
     * Only accessible by the game owner
     */
    function recordScoreEmergency(
        uint256 _score,
        string memory _playerName,
        address _playerAddress,
        bytes32 _gameHash
    ) public onlyGameOwner whenNotPaused {
        require(_score > 0, "Score must be greater than 0");
        require(!usedGameHashes[_gameHash], "Game hash already used");

        usedGameHashes[_gameHash] = true;

        Score memory newScore = Score({
            score: _score,
            timestamp: block.timestamp,
            playerName: _playerName,
            gameHash: _gameHash
        });

        playerScores[_playerAddress].push(newScore);

        // Add player to global tracking if not already present
        if (!playerExists[_playerAddress]) {
            allPlayers.push(_playerAddress);
            playerExists[_playerAddress] = true;
            playerNames[_playerAddress] = _playerName;
        }

        if (_score > playerBestScore[_playerAddress]) {
            playerBestScore[_playerAddress] = _score;
            emit BestScoreUpdated(_playerAddress, _score);
        }

        emit ScoreRecorded(_playerAddress, _score, block.timestamp, _gameHash);
    }

    /**
     * @dev Recovers the signer from a signature
     */
    function recoverSigner(
        bytes32 _ethSignedMessageHash,
        bytes memory _signature
    ) internal pure returns (address) {
        require(_signature.length == 65, "Invalid signature length");

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            r := mload(add(_signature, 32))
            s := mload(add(_signature, 64))
            v := byte(0, mload(add(_signature, 96)))
        }

        if (v < 27) {
            v += 27;
        }

        require(v == 27 || v == 28, "Invalid signature 'v' value");

        return ecrecover(_ethSignedMessageHash, v, r, s);
    }

    function getPlayerScores(
        address _player
    ) public view returns (Score[] memory) {
        return playerScores[_player];
    }

    function getPlayerBestScore(address _player) public view returns (uint256) {
        return playerBestScore[_player];
    }

    function getScoreCount(address _player) public view returns (uint256) {
        return playerScores[_player].length;
    }

    /**
     * @dev Gets the global leaderboard with pagination
     * @param _offset Starting index for pagination
     * @param _limit Number of entries to return
     * @return Array of LeaderboardEntry structs
     */
    function getLeaderboard(
        uint256 _offset,
        uint256 _limit
    ) public view returns (LeaderboardEntry[] memory) {
        uint256 totalPlayers = allPlayers.length;

        if (_offset >= totalPlayers) {
            return new LeaderboardEntry[](0);
        }

        uint256 endIndex = _offset + _limit;
        if (endIndex > totalPlayers) {
            endIndex = totalPlayers;
        }

        uint256 resultLength = endIndex - _offset;
        LeaderboardEntry[] memory result = new LeaderboardEntry[](resultLength);

        // Create a temporary array to sort by best scores
        LeaderboardEntry[] memory allEntries = new LeaderboardEntry[](
            totalPlayers
        );
        for (uint256 i = 0; i < totalPlayers; i++) {
            address player = allPlayers[i];
            allEntries[i] = LeaderboardEntry({
                score: playerBestScore[player],
                playerName: playerNames[player],
                playerAddress: player
            });
        }

        // Sort by score (descending) - simple bubble sort for small arrays
        for (uint256 i = 0; i < totalPlayers - 1; i++) {
            for (uint256 j = 0; j < totalPlayers - i - 1; j++) {
                if (allEntries[j].score < allEntries[j + 1].score) {
                    LeaderboardEntry memory temp = allEntries[j];
                    allEntries[j] = allEntries[j + 1];
                    allEntries[j + 1] = temp;
                }
            }
        }

        // Copy the requested range
        for (uint256 i = 0; i < resultLength; i++) {
            result[i] = allEntries[_offset + i];
        }

        return result;
    }

    /**
     * @dev Gets the total number of players in the leaderboard
     * @return Total number of players
     */
    function getTotalScores() public view returns (uint256) {
        return allPlayers.length;
    }

    /**
     * @dev Administrative functions
     */
    function setGameOwner(address _newOwner) public onlyGameOwner {
        require(_newOwner != address(0), "Invalid address");
        address oldOwner = gameOwner;
        gameOwner = _newOwner;
        emit GameOwnerUpdated(oldOwner, _newOwner);
    }

    function setPaused(bool _paused) public onlyGameOwner {
        paused = _paused;
        emit ContractPaused(_paused);
    }

    /**
     * @dev Sets the security key for signing scores
     * @param _securityKey The new security key
     */
    function setSecurityKey(bytes32 _securityKey) public onlyGameOwner {
        securityKey = _securityKey;
        securityKeySet = true;
        emit SecurityKeyUpdated(_securityKey);
    }

    function getContractInfo()
        public
        view
        returns (
            address _gameOwner,
            bool _paused,
            uint256 _minTimeBetweenScores,
            bool _securityKeySet
        )
    {
        return (gameOwner, paused, MIN_TIME_BETWEEN_SCORES, securityKeySet);
    }
}

